	static Vector3D smethod_23(buMarbleCalc buMarbleCalc_0, Vector3D vector3D_0)
	{
		double num = 1E-09;
		Vector3D vector3D = new Vector3D(vector3D_0.X, vector3D_0.Y, vector3D_0.Z);
		vector3D.Normalize();
		if (!(vector3D.X >= -1E-09) || (!(Math.Abs(vector3D.X) >= num) && vector3D.Y < 0.0 - num) || (!(Math.Abs(vector3D.X) >= num) && Math.Abs(vector3D.Y) < num && vector3D.Z < 0.0))
		{
			vector3D = new Vector3D(0.0 - vector3D.X, 0.0 - vector3D.Y, 0.0 - vector3D.Z);
		}
		return vector3D;
	}

