	static bool smethod_48(double double_0, ref ICurve[] icurve_0, LinkedList<SharedEdge>[] linkedList_0, Mesh mesh_0, [Out] Plane plane_0, buVector5 buVector5_0)
	{
		bool flag = false;
		double[] array = new double[3]
		{
			0.0,
			0.0 - double_0,
			2.0 * double_0
		};
		icurve_0 = null;
		Plane plane = (Plane)plane_0.Clone();
		int num = 0;
		while (!flag && num < array.Length)
		{
			if (array[num] != 0.0)
			{
				plane.Translate(new Vector3D(0.0, 0.0, array[num]));
			}
			icurve_0 = mesh_0.Section(plane, 0.0, linkedList_0);
			flag = icurve_0.Length != 0;
			ICurve[] array2 = icurve_0;
			foreach (ICurve curve in array2)
			{
				flag &= curve.IsClosed;
				Point3D[] vertices = ((LinearPath)curve).Vertices;
				foreach (Point3D point3D in vertices)
				{
					point3D.Z = plane_0.Origin.Z;
				}
			}
			num++;
		}
		if (!flag)
		{
			icurve_0 = new ICurve[0];
		}
		return flag;
	}

