		f_CornerLocation_0.btn_topcenter.BackColor = f_CornerLocation_0.color_1;
		f_CornerLocation_0.btn_topright.BackColor = f_CornerLocation_0.color_1;
		f_CornerLocation_0.btn_middleleft.BackColor = f_CornerLocation_0.color_1;
		f_CornerLocation_0.btn_middleright.BackColor = f_CornerLocation_0.color_1;
		f_CornerLocation_0.btn_bottomleft.BackColor = f_CornerLocation_0.color_1;
		f_CornerLocation_0.btn_bottomcenter.BackColor = f_CornerLocation_0.color_1;
		f_CornerLocation_0.btn_bottomright.BackColor = f_CornerLocation_0.color_1;
		if (f_CornerLocation_0.Corner != CornerLocation.LeftTop)
		{
			if (f_CornerLocation_0.Corner != CornerLocation.TopCenter)
			{
				if (f_CornerLocation_0.Corner != CornerLocation.RightTop)
				{
					if (f_CornerLocation_0.Corner != CornerLocation.LeftCenter)
					{
						if (f_CornerLocation_0.Corner != CornerLocation.RightCenter)
						{
							if (f_CornerLocation_0.Corner != CornerLocation.LeftBottom)
							{
								if (f_CornerLocation_0.Corner != CornerLocation.BottomCenter)
								{
									if (f_CornerLocation_0.Corner == CornerLocation.RightBottom)
									{
										f_CornerLocation_0.btn_bottomright.BackColor = f_CornerLocation_0.color_0;
									}
								}
								else
								{
									f_CornerLocation_0.btn_bottomcenter.BackColor = f_CornerLocation_0.color_0;
								}
							}
							else
							{
								f_CornerLocation_0.btn_bottomleft.BackColor = f_CornerLocation_0.color_0;
							}
						}
						else
						{
							f_CornerLocation_0.btn_middleright.BackColor = f_CornerLocation_0.color_0;
						}
					}
					else
					{
						f_CornerLocation_0.btn_middleleft.BackColor = f_CornerLocation_0.color_0;
					}
				}
				else
				{
					f_CornerLocation_0.btn_topright.BackColor = f_CornerLocation_0.color_0;
				}
			}
			else
			{
				f_CornerLocation_0.btn_topcenter.BackColor = f_CornerLocation_0.color_0;
			}
		}
		else
		{
			f_CornerLocation_0.btn_topleft.BackColor = f_CornerLocation_0.color_0;
		}
	}

