	static void smethod_74(F_NestedResults f_NestedResults_0)
	{
		if (!((f_NestedResults_0.int_1 >= 0) & (f_NestedResults_0.int_1 <= buNestingCalc.NestedAllResults.Count - 1)))
		{
			return;
		}
		for (int i = 0; i <= buNestingCalc.NestedAllResults[f_NestedResults_0.int_1].NestedResultSheets.Count - 1; i++)
		{
			string text = buNestingCalc.SheetItemFormat(buNestingCalc.NestedAllResults[f_NestedResults_0.int_1], f_NestedResults_0.strSheetName, i);
			if (buNestingCalc.NestedAllResults[f_NestedResults_0.int_1].NestedResultSheets[i].DontUse)
			{
				if ((f_NestedResults_0.int_1 >= 0) & (f_NestedResults_0.int_1 <= f_NestedResults_0.tree_nest.Nodes.Count - 1))
				{
					f_NestedResults_0.tree_nest.Nodes[f_NestedResults_0.int_1].Nodes[i].Text = "( - )  " + text;
					f_NestedResults_0.tree_nest.Nodes[f_NestedResults_0.int_1].Nodes[i].ForeColor = Color.Yellow;
				}
			}
			else if ((f_NestedResults_0.int_1 >= 0) & (f_NestedResults_0.int_1 <= f_NestedResults_0.tree_nest.Nodes.Count - 1))
			{
				f_NestedResults_0.tree_nest.Nodes[f_NestedResults_0.int_1].Nodes[i].Text = text;
				f_NestedResults_0.tree_nest.Nodes[f_NestedResults_0.int_1].Nodes[i].ForeColor = Color.Green;
			}
			if (buNestingCalc.NestedAllResults[f_NestedResults_0.int_1].NestedResultSheets[i].CalculationError)
			{
				f_NestedResults_0.tree_nest.Nodes[f_NestedResults_0.int_1].Nodes[i].Text = "( X )  " + text;
				f_NestedResults_0.tree_nest.Nodes[f_NestedResults_0.int_1].Nodes[i].ForeColor = Color.Red;
			}
		}
	}

