	static void smethod_78(F_AddFromFile f_AddFromFile_0)
	{
		f_AddFromFile_0.grid_files.Rows.Clear();
		int num = 1;
		for (int i = 0; i <= f_AddFromFile_0.list_1.Count - 1; i++)
		{
			string fileName = buFile.getFileName(f_AddFromFile_0.list_1[i]);
			FileInfo fileInfo = new FileInfo(f_AddFromFile_0.list_1[i]);
			double num2 = (double)fileInfo.Length / 1024.0 / 1024.0;
			f_AddFromFile_0.grid_files.Rows.Add(num, fileName + " | " + num2.ToString("f2") + " MB");
			num++;
		}
	}

