	static void smethod_86(F_ProfileCopy f_ProfileCopy_0)
	{
		if (!((f_ProfileCopy_0.OperationData.selectedPlaneName == planeNames.Top) | (f_ProfileCopy_0.OperationData.selectedPlaneName == planeNames.Bottom) | (f_ProfileCopy_0.OperationData.selectedPlaneName == planeNames.Free)))
		{
			f_ProfileCopy_0.OperationData.basePosition.X = (double)f_ProfileCopy_0.spn_x.Value;
			f_ProfileCopy_0.OperationData.basePosition.Y = (double)f_ProfileCopy_0.spn_y.Value;
			f_ProfileCopy_0.OperationData.basePosition.Z = (double)f_ProfileCopy_0.spn_y.Value;
		}
		else
		{
			f_ProfileCopy_0.OperationData.basePosition.X = (double)f_ProfileCopy_0.spn_x.Value;
			f_ProfileCopy_0.OperationData.basePosition.Y = (double)f_ProfileCopy_0.spn_y.Value;
		}
		f_ProfileCopy_0.UseOriginalPlane = f_ProfileCopy_0.checkBox_0.Checked;
		if (!f_ProfileCopy_0.radioButton_0.Checked)
		{
			f_ProfileCopy_0.UseDistance = false;
		}
		else
		{
			f_ProfileCopy_0.UseDistance = true;
		}
		f_ProfileCopy_0.Count = (int)f_ProfileCopy_0.spn_count.Value;
		f_ProfileCopy_0.DistanceHor = (double)f_ProfileCopy_0.spn_distancehor.Value;
		f_ProfileCopy_0.DistanceVer = (double)f_ProfileCopy_0.spn_distancever.Value;
	}

	static void smethod_87(F_ControlUIBasic f_ControlUIBasic_0)
	{
		string callMethod = "Profile Cut LoadLanguage";
		try
		{
			f_ControlUIBasic_0.buGround1.Text = buLangTranslate.preDef.Information;
			f_ControlUIBasic_0.btn_cancel.Text = buLangTranslate.preDef.Cancel;
			f_ControlUIBasic_0.btn_ok.Text = buLangTranslate.preDef.Ok;
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", callMethod);
			buException.throwException(mSException, callMethod, ShowMessageBox: true, text);
		}
	}

