	static void smethod_115(F_MarbleSawMillingVertical f_MarbleSawMillingVertical_0)
	{
		buMarbleCalc.varMarbleRunSettings.ScaleHeight = f_MarbleSawMillingVertical_0.spn_scaleheight.Value;
		buMarbleCalc.varMarbleRunSettings.ScaleWidth = f_MarbleSawMillingVertical_0.spn_scalewidth.Value;
		buMarbleCalc.varMarbleRunSettings.ScaleBaseHeight = f_MarbleSawMillingVertical_0.spn_baseheight.Value;
		buMarbleCalc.varMarbleRunSettings.ScaleKeepRatio = f_MarbleSawMillingVertical_0.chk_keepratio.Check;
		if (f_MarbleSawMillingVertical_0.CamMode != MarbleCamMode.Rough)
		{
			buMarbleCalc.varOperation.settingSawMilling.SawMillingFinishVerTopOffset = f_MarbleSawMillingVertical_0.spn_startzoffset.Value;
			buMarbleCalc.varOperation.settingSawMilling.SawMillingFinishVerBottomOffset = f_MarbleSawMillingVertical_0.spn_endzoffset.Value;
			buMarbleCalc.varOperation.settingSawMilling.SawMillingFinishVerMinZValue = f_MarbleSawMillingVertical_0.spn_minz.Value;
		}
		else
		{
			buMarbleCalc.varOperation.settingSawMilling.SawMillingRoughVerTopOffset = f_MarbleSawMillingVertical_0.spn_startzoffset.Value;
			buMarbleCalc.varOperation.settingSawMilling.SawMillingRoughVerBottomOffset = f_MarbleSawMillingVertical_0.spn_endzoffset.Value;
			buMarbleCalc.varOperation.settingSawMilling.SawMillingRoughVerMinZValue = f_MarbleSawMillingVertical_0.spn_minz.Value;
		}
	}

	static void smethod_116(F_CamSettings1 f_CamSettings1_0)
	{
		if (!f_CamSettings1_0.radioButton_1.Checked)
		{
			f_CamSettings1_0.CamPar.Pockets.PocketInOut = InToOutType.OutToIn;
		}
		else
		{
			f_CamSettings1_0.CamPar.Pockets.PocketInOut = InToOutType.InToOut;
		}
		f_CamSettings1_0.CamPar.Speeds.Feed = (double)f_CamSettings1_0.spn_vellfeed.Value;
		f_CamSettings1_0.CamPar.Speeds.Plunge = (double)f_CamSettings1_0.spn_velplunge.Value;
		f_CamSettings1_0.CamPar.Speeds.Finish = (double)f_CamSettings1_0.spn_finishvelocity.Value;
		f_CamSettings1_0.CamPar.Speeds.Pocket = (double)f_CamSettings1_0.spn_areaclearancevelocity.Value;
		f_CamSettings1_0.CamPar.Distances.Safe = (double)f_CamSettings1_0.spn_dissafe.Value;
		f_CamSettings1_0.CamPar.Distances.Rapid = (double)f_CamSettings1_0.spn_dissmallsafe.Value;
		f_CamSettings1_0.CamPar.Offsets.FinishOffset = (double)f_CamSettings1_0.spn_finishoffset.Value;
		f_CamSettings1_0.CamPar.Steps.NumberOfSlice = (int)f_CamSettings1_0.spn_stepcount.Value;
		f_CamSettings1_0.CamPar.Pockets.StepOverPersentage = (double)f_CamSettings1_0.numericUpDown_0.Value;
		f_CamSettings1_0.CamPar.Pockets.Enable = f_CamSettings1_0.checkBox_1.Checked;
		f_CamSettings1_0.CamPar.Operations.FinishEnable = f_CamSettings1_0.checkBox_3.Checked;
		f_CamSettings1_0.CamPar.Steps.Enable = f_CamSettings1_0.checkBox_0.Checked;
		f_CamSettings1_0.CamPar.Strategy.OpenContourTwoDirectionCut = f_CamSettings1_0.checkBox_2.Checked;
		f_CamSettings1_0.CamPar.Speeds.AreaClearanceEnable = f_CamSettings1_0.checkBox_1.Checked;
		f_CamSettings1_0.CamPar.LeadIn.Length = (double)f_CamSettings1_0.spn_leadin.Value;
		f_CamSettings1_0.CamPar.LeadOut.Length = (double)f_CamSettings1_0.spn_leadout.Value;
		if (!f_CamSettings1_0.radioButton_2.Checked)
		{
			f_CamSettings1_0.CamPar.Operations.Direction = ClockDirectionType.CW;
		}
		else
		{
			f_CamSettings1_0.CamPar.Operations.Direction = ClockDirectionType.CCW;
		}
		if (!f_CamSettings1_0.radioButton_5.Checked)
		{
			if (!f_CamSettings1_0.radioButton_6.Checked)
			{
				f_CamSettings1_0.CamPar.Offsets.ClosedContour = CamClosedContourType.Outter;
			}
			else
			{
				f_CamSettings1_0.CamPar.Offsets.ClosedContour = CamClosedContourType.Inner;
			}
		}
		else
		{
			f_CamSettings1_0.CamPar.Offsets.ClosedContour = CamClosedContourType.Center;
		}
		if (!f_CamSettings1_0.radioButton_8.Checked)
		{
			if (!f_CamSettings1_0.radioButton_9.Checked)
			{
				f_CamSettings1_0.CamPar.Offsets.OpenContour = CamOpenContourType.Right;
			}
			else
			{
				f_CamSettings1_0.CamPar.Offsets.OpenContour = CamOpenContourType.Left;
			}
		}
		else
		{
			f_CamSettings1_0.CamPar.Offsets.OpenContour = CamOpenContourType.Center;
		}
	}

	static void smethod_117(F_MarblePhotoCalibration f_MarblePhotoCalibration_0)
	{
		string callMethod = "Profile Cut LoadLanguage";
		try
		{
			f_MarblePhotoCalibration_0.buGround_0.Text = buLangTranslate.preDef.Photo + " " + buLangTranslate.preDef.Setting;
			f_MarblePhotoCalibration_0.spn_basex.Caption.Caption = buLangTranslate.preDef.Base + " " + buLangTranslate.preChar.X;
			f_MarblePhotoCalibration_0.spn_bssey.Caption.Caption = buLangTranslate.preDef.Base + " " + buLangTranslate.preChar.Y;
			f_MarblePhotoCalibration_0.spn_firstx.Caption.Caption = buLangTranslate.preDef.First + " " + buLangTranslate.preChar.X;
			f_MarblePhotoCalibration_0.spn_firsty.Caption.Caption = buLangTranslate.preDef.First + " " + buLangTranslate.preChar.Y;
			f_MarblePhotoCalibration_0.spn_firstthinckness.Caption.Caption = buLangTranslate.preDef.First + " " + buLangTranslate.preDef.Thickness;
			f_MarblePhotoCalibration_0.spn_secondx.Caption.Caption = buLangTranslate.preDef.Second + " " + buLangTranslate.preChar.X;
			f_MarblePhotoCalibration_0.spn_secondy.Caption.Caption = buLangTranslate.preDef.Second + " " + buLangTranslate.preChar.Y;
			f_MarblePhotoCalibration_0.spn_secondthickness.Caption.Caption = buLangTranslate.preDef.Second + " " + buLangTranslate.preDef.Thickness;
			f_MarblePhotoCalibration_0.btn_ok.Text = buLangTranslate.preDef.Ok;
			f_MarblePhotoCalibration_0.btn_cancel.Text = buLangTranslate.preDef.Cancel;
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", callMethod);
			buException.throwException(mSException, callMethod, ShowMessageBox: true, text);
		}
	}

