	{
		double num = 0.0;
		double num2 = 0.0;
		double num3 = 0.0;
		double num4 = 0.0;
		if (!((list_2.Count > 0) & (list_0.Count > 0)))
		{
			throw new RegisterException(string_1);
		}
		for (int i = 0; i <= list_2.Count - 1; i++)
		{
			num = 0.0;
			num2 = 0.0;
			num3 = 0.0;
			for (int j = 0; j <= list_2[i].Length - 1; j++)
			{
				string value = list_2[i].Substring(j, 1);
				double num5 = (int)Convert.ToByte(Convert.ToChar(value));
				num += num5 * 17.92;
			}
			for (int k = 0; k <= list_0[0].Length - 1; k++)
			{
				string value2 = list_0[0].Substring(k, 1);
				double num6 = (int)Convert.ToByte(Convert.ToChar(value2));
				num2 += num6 * 47.93;
			}
			for (int l = 0; l <= string_0.Length - 1; l++)
			{
				string value3 = string_0.Substring(l, 1);
