	static void smethod_146(F_MarbleEngraveCamSetting f_MarbleEngraveCamSetting_0, ref camParameters5 camParameters5_0)
	{
		if (!f_MarbleEngraveCamSetting_0.chk_oneway.Check)
		{
			if (!f_MarbleEngraveCamSetting_0.chk_spiral.Check)
			{
				camParameters5_0.Strategy.CuttingMethod = CamCuttingMethod.MachtypeZigzag;
			}
			else
			{
				camParameters5_0.Strategy.CuttingMethod = CamCuttingMethod.MachtypeSpiral;
			}
		}
		else
		{
			camParameters5_0.Strategy.CuttingMethod = CamCuttingMethod.MachtypeOneway;
		}
		if (!f_MarbleEngraveCamSetting_0.chk_level.Check)
		{
			camParameters5_0.Strategy.MachiningAreaMode = CamMachiningAreaMode.MachByRegions;
		}
		else
		{
			camParameters5_0.Strategy.MachiningAreaMode = CamMachiningAreaMode.MachByLanes;
		}
		if (f_MarbleEngraveCamSetting_0.chk_silhouettenone.Check)
		{
			camParameters5_0.Strategy.SilhouetteEnable = false;
		}
		else
		{
			camParameters5_0.Strategy.SilhouetteEnable = true;
			if (!f_MarbleEngraveCamSetting_0.chk_silhouettepartend.Check)
			{
				if (!f_MarbleEngraveCamSetting_0.chk_silhouettetoolcontact.Check)
				{
					camParameters5_0.Strategy.SilhouetteTriangleMeshType = CamSilhouetteContainmentTriangleMeshType.ScctPartSilhouette;
				}
				else
				{
					camParameters5_0.Strategy.SilhouetteTriangleMeshType = CamSilhouetteContainmentTriangleMeshType.ScctToolContact;
				}
			}
