	static void smethod_179(F_ControlUISettings f_ControlUISettings_0)
	{
		string callMethod = "Profile Cut LoadLanguage";
		try
		{
			f_ControlUISettings_0.buGround1.Text = buLangTranslate.preDef.Information;
			f_ControlUISettings_0.btn_ok.Text = buLangTranslate.preDef.Ok;
			f_ControlUISettings_0.btn_cancel.Text = buLangTranslate.preDef.Cancel;
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", callMethod);
			buException.throwException(mSException, callMethod, ShowMessageBox: true, text);
		}
	}

	static void smethod_180(F_NestSheetPartList f_NestSheetPartList_0)
	{
		double num = 0.0;
		double num2 = 0.0;
		double num3 = 0.0;
		for (int i = 0; i <= f_NestSheetPartList_0.Parts.Count - 1; i++)
		{
			if (f_NestSheetPartList_0.Parts[i].Enable)
			{
				num += f_NestSheetPartList_0.Parts[i].PartData.Width / 1000.0 * (f_NestSheetPartList_0.Parts[i].PartData.Height / 1000.0) * Convert.ToDouble(f_NestSheetPartList_0.Parts[i].PartData.Quantity);
			}
			if (i <= f_NestSheetPartList_0.dataGridView_1.Rows.Count - 1)
			{
				f_NestSheetPartList_0.dataGridView_1.Rows[i].Cells[8].Value = f_NestSheetPartList_0.Parts[i].Remain;
			}
		}
		for (int j = 0; j <= f_NestSheetPartList_0.Sheets.Count - 1; j++)
		{
			if ((f_NestSheetPartList_0.Sheets[j].MaterialData.Quantity > 0) & f_NestSheetPartList_0.Sheets[j].Enable)
			{
				num2 += f_NestSheetPartList_0.Sheets[j].MaterialData.Width / 1000.0 * (f_NestSheetPartList_0.Sheets[j].MaterialData.Height / 1000.0) * Convert.ToDouble(f_NestSheetPartList_0.Sheets[j].MaterialData.Quantity);
			}
			if (j <= f_NestSheetPartList_0.dataGridView_0.Rows.Count - 1)
			{
				f_NestSheetPartList_0.dataGridView_0.Rows[j].Cells[8].Value = f_NestSheetPartList_0.Sheets[j].Remain;
			}
		}
		f_NestSheetPartList_0.textBox_3.Text = num.ToString("f2");
		f_NestSheetPartList_0.textBox_2.Text = num3.ToString("f2");
		f_NestSheetPartList_0.textBox_1.Text = num2.ToString("f2");
		f_NestSheetPartList_0.textBox_0.Text = num2.ToString("f2");
		f_NestSheetPartList_0.GetInfo();
	}

