	static void smethod_219(F_MarblePhotoCalibration f_MarblePhotoCalibration_0)
	{
		buMarbleCalc.varMarbleRunSettings.CameraBaseXPosition = f_MarblePhotoCalibration_0.spn_basex.Value;
		buMarbleCalc.varMarbleRunSettings.CameraBaseYPosition = f_MarblePhotoCalibration_0.spn_bssey.Value;
		buMarbleCalc.varMarbleRunSettings.CameraFirstXPosition = f_MarblePhotoCalibration_0.spn_firstx.Value;
		buMarbleCalc.varMarbleRunSettings.CameraFirstYPosition = f_MarblePhotoCalibration_0.spn_firsty.Value;
		buMarbleCalc.varMarbleRunSettings.CameraFirstMaterial = f_MarblePhotoCalibration_0.spn_firstthinckness.Value;
		buMarbleCalc.varMarbleRunSettings.CameraSecondXPosition = f_MarblePhotoCalibration_0.spn_secondx.Value;
		buMarbleCalc.varMarbleRunSettings.CameraSecondYPosition = f_MarblePhotoCalibration_0.spn_secondy.Value;
		buMarbleCalc.varMarbleRunSettings.CameraSecondMaterial = f_MarblePhotoCalibration_0.spn_secondthickness.Value;
		buMarbleCalc.varMarbleSettings.CameraLensXRatio = (buMarbleCalc.varMarbleRunSettings.CameraSecondMaterial - 0.0) / (buMarbleCalc.varMarbleRunSettings.CameraSecondXPosition - buMarbleCalc.varMarbleRunSettings.CameraBaseXPosition);
		buMarbleCalc.varMarbleSettings.CameraLensYRatio = (buMarbleCalc.varMarbleRunSettings.CameraSecondMaterial - 0.0) / (buMarbleCalc.varMarbleRunSettings.CameraSecondYPosition - buMarbleCalc.varMarbleRunSettings.CameraBaseYPosition);
		double XOffset = 0.0;
		double YOffset = 0.0;
		double WidthOffset = 0.0;
		double HegihtOffset = 0.0;
		buCall.buMarbleCalc_0.CameraNewPositionandSizeCalculation(100.0, ref XOffset, ref YOffset, ref WidthOffset, ref HegihtOffset);
	}

