	static void smethod_230(F_CamSettings f_CamSettings_0)
	{
		if (!f_CamSettings_0.radioButton_1.Checked)
		{
			f_CamSettings_0.CamPar.Operations.AreaClearanceDirection = InToOutType.OutToIn;
		}
		else
