		f_CamSettings_0.CamPar.Distances.Safe = (double)f_CamSettings_0.spn_dissafe.Value;
		f_CamSettings_0.CamPar.Distances.Rapid = (double)f_CamSettings_0.spn_dissmallsafe.Value;
		f_CamSettings_0.CamPar.Offsets.FinishOffset = (double)f_CamSettings_0.spn_finishoffset.Value;
