		f_CamSettings_0.CamPar.Operations.DepthUp = (double)f_CamSettings_0.spn_depthup.Value;
		f_CamSettings_0.CamPar.Operations.AreaClearanceEnable = f_CamSettings_0.checkBox_1.Checked;
		f_CamSettings_0.CamPar.Operations.FinishEnable = f_CamSettings_0.checkBox_2.Checked;
		f_CamSettings_0.CamPar.Steps.Enable = f_CamSettings_0.checkBox_0.Checked;
