				f_CamSettings_0.CamPar.Pockets.PocketType = CamPocketType.WfbRghtParallel;
			}
		}
		else
		{
			f_CamSettings_0.CamPar.Pockets.PocketType = CamPocketType.WfbRghtOffset;
		}
		if (!f_CamSettings_0.radioButton_2.Checked)
		{
			f_CamSettings_0.CamPar.Operations.Direction = ClockDirectionType.CW;
		}
		else
		{
			f_CamSettings_0.CamPar.Operations.Direction = ClockDirectionType.CCW;
		}
		if (!f_CamSettings_0.radioButton_5.Checked)
		{
			if (!f_CamSettings_0.radioButton_6.Checked)
			{
				f_CamSettings_0.CamPar.Offsets.ClosedContour = CamClosedContourType.Outter;
			}
			else
			{
				f_CamSettings_0.CamPar.Offsets.ClosedContour = CamClosedContourType.Inner;
			}
		}
		else
		{
			f_CamSettings_0.CamPar.Offsets.ClosedContour = CamClosedContourType.Center;
		}
		if (!f_CamSettings_0.radioButton_8.Checked)
		{
			if (!f_CamSettings_0.radioButton_9.Checked)
			{
				f_CamSettings_0.CamPar.Offsets.OpenContour = CamOpenContourType.Right;
			}
			else
			{
				f_CamSettings_0.CamPar.Offsets.OpenContour = CamOpenContourType.Left;
			}
		}
		else
		{
			f_CamSettings_0.CamPar.Offsets.OpenContour = CamOpenContourType.Center;
		}
	}

