	static void smethod_296(buEyeBaseVer5.Forms.KeyPad.Form1 form1_0)
	{
		form1_0.Text = "Pro Calculator";
		form1_0.Size = new Size(420, 600);
		form1_0.BackColor = Color.FromArgb(18, 18, 22);
		form1_0.FormBorderStyle = FormBorderStyle.FixedSingle;
		form1_0.MaximizeBox = false;
		form1_0.textBox_0.Font = new Font("Segoe UI", 24f, FontStyle.Bold);
		form1_0.textBox_0.BackColor = Color.FromArgb(30, 30, 35);
		form1_0.textBox_0.ForeColor = Color.White;
		form1_0.textBox_0.BorderStyle = BorderStyle.None;
		form1_0.textBox_0.TextAlign = HorizontalAlignment.Right;
		form1_0.textBox_0.Text = "0";
		form1_0.listBox_0.BackColor = Color.FromArgb(25, 25, 30);
		form1_0.listBox_0.ForeColor = Color.LightGray;
		form1_0.listBox_0.BorderStyle = BorderStyle.None;
		string[,] array = new string[6, 4]
		{
			{ "MC", "MR", "M+", "M-" },
			{ "7", "8", "9", "/" },
			{ "4", "5", "6", "*" },
			{ "1", "2", "3", "-" },
			{ "0", ".", "=", "+" },
			{ "C", "(", ")", "⌫" }
		};
		int num = 5;
		int num2 = 50;
		int num3 = 60;
		for (int i = 0; i < array.GetLength(0); i++)
		{
			for (int j = 0; j < array.GetLength(1); j++)
			{
				Button button = new Button();
				button.Text = array[i, j];
				button.Size = new Size(num3, num3);
				button.Location = new System.Drawing.Point(num + j * (num3 + 5), num2 + i * (num3 + 5));
				button.FlatStyle = FlatStyle.Flat;
				button.FlatAppearance.BorderSize = 0;
				button.Font = new Font("Segoe UI", 12f, FontStyle.Bold);
				button.ForeColor = Color.White;
				if (!"+-*/".Contains(button.Text))
				{
					if (!(button.Text == "="))
					{
						if (!(button.Text == "C") && !(button.Text == "⌫"))
						{
							if (!button.Text.StartsWith("M"))
							{
								button.BackColor = Color.FromArgb(40, 40, 50);
							}
							else
							{
								button.BackColor = Color.FromArgb(80, 80, 100);
							}
						}
						else
						{
							button.BackColor = Color.FromArgb(180, 60, 60);
						}
					}
					else
					{
						button.BackColor = Color.FromArgb(0, 120, 215);
					}
				}
				else
				{
					button.BackColor = Color.FromArgb(60, 60, 80);
				}
				button.Click += form1_0.method_1;
				form1_0.Controls.Add(button);
			}
		}
	}

