	static void smethod_302(F_ControlUIRadio f_ControlUIRadio_0)
	{
		string callMethod = "Profile Cut LoadLanguage";
		try
		{
			f_ControlUIRadio_0.buGround1.Text = buLangTranslate.preDef.Information;
			f_ControlUIRadio_0.btn_cancel.Text = buLangTranslate.preDef.Cancel;
			f_ControlUIRadio_0.btn_ok.Text = buLangTranslate.preDef.Ok;
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", callMethod);
			buException.throwException(mSException, callMethod, ShowMessageBox: true, text);
		}
	}

	static void smethod_303(F_RoboticSurfacePoints f_RoboticSurfacePoints_0)
	{
		f_RoboticSurfacePoints_0.dataGridView_0.Rows.Clear();
		for (int i = 0; i <= f_RoboticSurfacePoints_0.SurfPoints.Count - 1; i++)
		{
			if (f_RoboticSurfacePoints_0.isTangent)
			{
				DataGridViewRowCollection rows = f_RoboticSurfacePoints_0.dataGridView_0.Rows;
				bool enable = f_RoboticSurfacePoints_0.SurfPoints[i].Enable;
				double x = f_RoboticSurfacePoints_0.SurfPoints[i].pntTangent.X;
				double y = f_RoboticSurfacePoints_0.SurfPoints[i].pntTangent.Y;
				double z = f_RoboticSurfacePoints_0.SurfPoints[i].pntTangent.Z;
				double a = f_RoboticSurfacePoints_0.SurfPoints[i].pntTangent.A;
				double b = f_RoboticSurfacePoints_0.SurfPoints[i].pntTangent.B;
				double c = f_RoboticSurfacePoints_0.SurfPoints[i].pntTangent.C;
				rows.Add(smethod_105(x, i + 1, f_RoboticSurfacePoints_0, c, a, y, z, enable, b));
			}
			else
			{
				DataGridViewRowCollection rows2 = f_RoboticSurfacePoints_0.dataGridView_0.Rows;
				bool enable = f_RoboticSurfacePoints_0.SurfPoints[i].Enable;
				double x = f_RoboticSurfacePoints_0.SurfPoints[i].pntNormal.X;
				double y = f_RoboticSurfacePoints_0.SurfPoints[i].pntNormal.Y;
				double z = f_RoboticSurfacePoints_0.SurfPoints[i].pntNormal.Z;
				double a = f_RoboticSurfacePoints_0.SurfPoints[i].vecNormal.X;
				double b = f_RoboticSurfacePoints_0.SurfPoints[i].vecNormal.Y;
				double c = f_RoboticSurfacePoints_0.SurfPoints[i].vecNormal.Z;
				rows2.Add(smethod_105(x, i + 1, f_RoboticSurfacePoints_0, c, a, y, z, enable, b));
			}
			f_RoboticSurfacePoints_0.dataGridView_0.Rows[i].DefaultCellStyle.ForeColor = Color.Black;
			f_RoboticSurfacePoints_0.dataGridView_0.Rows[i].Height = 30;
		}
		f_RoboticSurfacePoints_0.PropertiesForm.Inited = true;
	}

