	static void smethod_323(F_MaterialRect3D f_MaterialRect3D_0)
	{
		if (!f_MaterialRect3D_0.PropertiesForm.Inited)
		{
			return;
		}
		f_MaterialRect3D_0.viewportLayout.Entities.Clear();
		CompositeCurve outters = CompositeCurve.CreateRectangle(f_MaterialRect3D_0.Material.Size.Width, f_MaterialRect3D_0.Material.Size.Height);
		Entity entSurface = null;
		buCall.buVector5_0.surfaceFromOutterInner(outters, null, f_MaterialRect3D_0.Material.Size.Depth, ref entSurface);
		entSurface.Color = f_MaterialRect3D_0.Material.Display.SkinColor;
		entSurface.ColorMethod = colorMethodType.byEntity;
		entSurface.Rotate(buConversion5.DegreeToRadian(f_MaterialRect3D_0.Material.Angle), Vector3D.AxisZ);
		f_MaterialRect3D_0.viewportLayout.Entities.Add(entSurface);
		if (f_MaterialRect3D_0.OptionEntity != null)
		{
			for (int i = 0; i <= f_MaterialRect3D_0.OptionEntity.Count - 1; i++)
			{
				f_MaterialRect3D_0.viewportLayout.Entities.Add(f_MaterialRect3D_0.OptionEntity[i]);
			}
		}
		if (f_MaterialRect3D_0.EntClamper != null)
		{
			f_MaterialRect3D_0.EntClamper.Regen(0.01);
			double clamperLength = f_MaterialRect3D_0.EntClamper.BoxMax.X - f_MaterialRect3D_0.EntClamper.BoxMin.X;
			double X = 0.0;
			double X2 = 0.0;
			f_MaterialRect3D_0.FindFirstClamperPositions(f_MaterialRect3D_0.Material.Size.Width, clamperLength, ref X, ref X2);
			Entity copiedEntity = null;
			Entity copiedEntity2 = null;
			buEntity.Copy(f_MaterialRect3D_0.EntClamper, ref copiedEntity);
			copiedEntity.Rotate(Math.PI, Vector3D.AxisZ);
			copiedEntity.Translate(X, 0.0);
			copiedEntity.LayerName = "Default";
			copiedEntity.Color = Color.Gray;
			copiedEntity.ColorMethod = colorMethodType.byEntity;
			buEntity.Copy(f_MaterialRect3D_0.EntClamper, ref copiedEntity2);
			copiedEntity2.Rotate(Math.PI, Vector3D.AxisZ);
			copiedEntity2.Translate(X2, 0.0);
			copiedEntity2.LayerName = "Default";
			copiedEntity2.Color = Color.Gray;
			copiedEntity2.ColorMethod = colorMethodType.byEntity;
			f_MaterialRect3D_0.viewportLayout.Entities.Add(copiedEntity);
			f_MaterialRect3D_0.viewportLayout.Entities.Add(copiedEntity2);
		}
		f_MaterialRect3D_0.viewportLayout.ActiveViewport.OriginSymbol.StyleMode = originSymbolStyleType.Ball;
		f_MaterialRect3D_0.viewportLayout.SetView(viewType.Top, fit: true, animate: false);
		f_MaterialRect3D_0.viewportLayout.ActiveViewport.RotateCamera(Vector3D.AxisZ, 180.0, trackBall: false);
		f_MaterialRect3D_0.viewportLayout.ActiveViewport.RotateCamera(Vector3D.AxisX, 45.0, trackBall: false);
		f_MaterialRect3D_0.viewportLayout.ZoomFit(10);
		f_MaterialRect3D_0.viewportLayout.Invalidate();
	}

	static void smethod_324(F_BarCode f_BarCode_0)
