	static void smethod_394(F_ControlUIText f_ControlUIText_0)
	{
		string callMethod = "Profile Cut LoadLanguage";
		try
		{
			f_ControlUIText_0.buGround1.Text = buLangTranslate.preDef.Information;
			f_ControlUIText_0.btn_cancel.Text = buLangTranslate.preDef.Cancel;
			f_ControlUIText_0.btn_ok.Text = buLangTranslate.preDef.Ok;
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", callMethod);
			buException.throwException(mSException, callMethod, ShowMessageBox: true, text);
		}
	}

	static void smethod_395(F_AnalyseResult f_AnalyseResult_0)
	{
		f_AnalyseResult_0.dataGridView_0.Rows.Clear();
		for (int i = 0; i <= f_AnalyseResult_0.Result.ErrorList.Count - 1; i++)
		{
			AnalyseEntitiesResultError analyseEntitiesResultError = new AnalyseEntitiesResultError(f_AnalyseResult_0.Result.ErrorList[i]);
			DataGridViewRowCollection rows = f_AnalyseResult_0.dataGridView_0.Rows;
			bool enable = analyseEntitiesResultError.Enable;
			string string_ = analyseEntitiesResultError.ErrorType.ToString();
			int indexEntity = analyseEntitiesResultError.IndexEntity;
			Enum enum_ = analyseEntitiesResultError.Action;
			rows.Add(smethod_470(string_, f_AnalyseResult_0, enable, i + 1, indexEntity, enum_));
			f_AnalyseResult_0.dataGridView_0.Rows[i].Height = 40;
		}
		f_AnalyseResult_0.PropertiesForm.Inited = true;
	}

