	static void smethod_435(F_MarbleCavity f_MarbleCavity_0)
	{
		f_MarbleCavity_0.varSettings.CavityLength = f_MarbleCavity_0.spn_length.Value;
		f_MarbleCavity_0.varSettings.CavityHeight = f_MarbleCavity_0.spn_height.Value;
		f_MarbleCavity_0.varSettings.CavityAngle = f_MarbleCavity_0.spn_ang.Value;
		f_MarbleCavity_0.varSettings.CavityCount = (int)f_MarbleCavity_0.spn_count.Value;
		f_MarbleCavity_0.varSettings.CavitySpace = f_MarbleCavity_0.spn_space.Value;
		f_MarbleCavity_0.varSettings.CavityDepth = f_MarbleCavity_0.spn_depth.Value;
		f_MarbleCavity_0.varSettings.CavityZigzagMode = f_MarbleCavity_0.chk_zigzag.Check;
		if (!f_MarbleCavity_0.chk_toolsaw.Check)
		{
			if (!f_MarbleCavity_0.chk_toolmillinghead.Check)
			{
				f_MarbleCavity_0.ToolType = MarbleToolType.Milling;
			}
			else
			{
				f_MarbleCavity_0.ToolType = MarbleToolType.MillingHead;
			}
		}
		else
		{
			f_MarbleCavity_0.ToolType = MarbleToolType.Saw;
		}
	}

