		f_PlaneSettings_0.Plane.UseCenterPoint = f_PlaneSettings_0.checkBox_0.Checked;
		f_PlaneSettings_0.Plane.isCircular = f_PlaneSettings_0.checkBox_1.Checked;
		f_PlaneSettings_0.Plane.CircularAngle = (double)f_PlaneSettings_0.numericUpDown_4.Value;
