	static void smethod_502(string string_0, F_ProfileAdd f_ProfileAdd_0)
	{
		try
		{
			FileInfo fileInfo = new FileInfo(string_0);
			if (f_ProfileAdd_0.design_0 == null || !f_ProfileAdd_0.design_0.IsHandleCreated)
			{
				return;
			}
			if (fileInfo.Extension.ToLower() == ".dxf")
			{
				buFile5.OpenDxfDwg(ref f_ProfileAdd_0.design_0, string_0);
				for (int i = 0; i <= f_ProfileAdd_0.design_0.Entities.Count - 1; i++)
				{
					if (!(f_ProfileAdd_0.design_0.Entities[i] is ICurve))
					{
					}
				}
				Point3D MinPoint = new Point3D();
				Point3D MidPoint = new Point3D();
				Point3D MaxPoint = new Point3D();
				buCall.buVector5_0.BoxSizeCalculate(f_ProfileAdd_0.design_0.Entities, ref MinPoint, ref MidPoint, ref MaxPoint);
				f_ProfileAdd_0.design_0.Entities.Translate(0.0 - MaxPoint.X, 0.0 - MinPoint.Y, 0.0 - MinPoint.Z);
				f_ProfileAdd_0.design_0.Entities.RegenAllCurved();
				f_ProfileAdd_0.design_0.Entities.Regen();
				f_ProfileAdd_0.design_0.SetView(viewType.Top);
				f_ProfileAdd_0.design_0.RotateLeft(180.0);
				f_ProfileAdd_0.design_0.ZoomFit();
				f_ProfileAdd_0.design_0.Invalidate();
			}
			if (!(fileInfo.Extension == ".bucad"))
			{
			}
			buCall.buVector5_0.BoxSizeCalculate(f_ProfileAdd_0.design_0.Entities, ref f_ProfileAdd_0.point3D_0, ref f_ProfileAdd_0.point3D_1, ref f_ProfileAdd_0.point3D_2);
			f_ProfileAdd_0.textBox_2.Text = buFile.getFileName(string_0);
			f_ProfileAdd_0.PropertiesForm.Inited = false;
			f_ProfileAdd_0.numericUpDown_5.Value = (decimal)(f_ProfileAdd_0.point3D_2.X - f_ProfileAdd_0.point3D_0.X);
			f_ProfileAdd_0.numericUpDown_6.Value = (decimal)(f_ProfileAdd_0.point3D_2.Y - f_ProfileAdd_0.point3D_0.Y);
			f_ProfileAdd_0.PropertiesForm.Inited = true;
		}
		catch (Exception)
		{
		}
	}

