	static void smethod_504(string string_0, F_SketchLibrary f_SketchLibrary_0)
	{
		try
		{
			DirectoryInfo directoryInfo = new DirectoryInfo(AppPath.Base + "\\L");
			if (!directoryInfo.Exists)
			{
				directoryInfo.Create();
			}
			buFile5.ExtractToFolder(directoryInfo.FullName, string_0);
			List<string> Files = new List<string>();
			buFile5.getFiles(AppPath.Base + "\\L", ref Files);
			string text = "";
			f_SketchLibrary_0.OpenCustomData = new List<EditorCustomData>();
			for (int i = 0; i <= Files.Count - 1; i++)
			{
				FileInfo fileInfo = new FileInfo(Files[i]);
				if (fileInfo.Exists)
				{
					if (fileInfo.Extension == ".buLibEye")
					{
						text = fileInfo.FullName;
					}
					if (!(fileInfo.Extension == ".buLibSet"))
					{
					}
				}
			}
			if (text.Length > 0)
			{
				ReadFile workUnit = new ReadFile(text);
				f_SketchLibrary_0.viewport.Clear();
				f_SketchLibrary_0.viewport.StartWork(workUnit);
			}
		}
		catch (Exception)
		{
		}
	}

	static void smethod_505(int int_0, F_LaserMaterial f_LaserMaterial_0)
	{
		f_LaserMaterial_0.listBox_1.Items.Clear();
