		if (!f_MarbleContour_0.chk_concavecuttingMilling.Check)
		{
			if (!f_MarbleContour_0.chk_concavecuttingWaterjet.Check)
			{
				f_MarbleContour_0.varSettings.settingMarbleCam.ConcaveCuttingType = MarbleConcaveCuttingType.None;
			}
			else
			{
				f_MarbleContour_0.varSettings.settingMarbleCam.ConcaveCuttingType = MarbleConcaveCuttingType.WaterJet;
			}
		}
		else
		{
			f_MarbleContour_0.varSettings.settingMarbleCam.ConcaveCuttingType = MarbleConcaveCuttingType.Milling;
		}
		if (!f_MarbleContour_0.chk_concexcuttingmilling.Check)
		{
			if (!f_MarbleContour_0.chk_concexcuttingWaterjet.Check)
			{
				f_MarbleContour_0.varSettings.settingMarbleCam.ConvexCuttingType = MarbleConcaveCuttingType.None;
			}
			else
			{
				f_MarbleContour_0.varSettings.settingMarbleCam.ConvexCuttingType = MarbleConcaveCuttingType.WaterJet;
			}
		}
		else
		{
			f_MarbleContour_0.varSettings.settingMarbleCam.ConvexCuttingType = MarbleConcaveCuttingType.Milling;
		}
	}

