	static void smethod_521(F_DoorMat f_DoorMat_0)
	{
		if (f_DoorMat_0.PropertiesForm.Inited)
		{
			f_DoorMat_0.viewportLayout.Entities.Clear();
			Entity entDoor = null;
			buCall.buDoor_0.CreateDoorEntityFromMaterial(f_DoorMat_0.Material, ref entDoor);
			CompositeCurve outters = CompositeCurve.CreateRectangle(f_DoorMat_0.Material.Size.Width, f_DoorMat_0.Material.Size.Height);
			Entity entSurface = null;
			buCall.buVector5_0.surfaceFromOutterInner(outters, null, f_DoorMat_0.Material.Size.Depth, ref entSurface);
			if (entDoor != null)
			{
				entDoor.Color = f_DoorMat_0.Material.Display.SkinColor;
				entDoor.ColorMethod = colorMethodType.byEntity;
				f_DoorMat_0.viewportLayout.Entities.Add(entDoor);
				f_DoorMat_0.viewportLayout.ActiveViewport.OriginSymbol.StyleMode = originSymbolStyleType.CoordinateSystem;
				f_DoorMat_0.viewportLayout.SetView(viewType.Isometric, fit: true, animate: false);
				f_DoorMat_0.viewportLayout.Invalidate();
			}
		}
	}

