	static void smethod_540(F_ProfileAdd f_ProfileAdd_0)
	{
		f_ProfileAdd_0.grid_files.Rows.Clear();
		int num = 1;
		for (int i = 0; i <= f_ProfileAdd_0.list_1.Count - 1; i++)
		{
			string fileName = buFile.getFileName(f_ProfileAdd_0.list_1[i]);
			f_ProfileAdd_0.grid_files.Rows.Add(num, fileName);
			num++;
		}
		if (f_ProfileAdd_0.list_1.Count > 0)
