	static void smethod_582(F_PanelCutNestSheetPartList f_PanelCutNestSheetPartList_0)
	{
		double num = 0.0;
		double num2 = 0.0;
		double num3 = 0.0;
		for (int i = 0; i <= f_PanelCutNestSheetPartList_0.Parts.Count - 1; i++)
		{
			if (f_PanelCutNestSheetPartList_0.Parts[i].Enable)
			{
				num += f_PanelCutNestSheetPartList_0.Parts[i].PartData.Width / 1000.0 * (f_PanelCutNestSheetPartList_0.Parts[i].PartData.Height / 1000.0) * Convert.ToDouble(f_PanelCutNestSheetPartList_0.Parts[i].PartData.Quantity);
			}
			if (i <= f_PanelCutNestSheetPartList_0.dataGridView_1.Rows.Count - 1)
			{
				f_PanelCutNestSheetPartList_0.dataGridView_1.Rows[i].Cells[8].Value = f_PanelCutNestSheetPartList_0.Parts[i].Remain;
			}
		}
		for (int j = 0; j <= f_PanelCutNestSheetPartList_0.Sheets.Count - 1; j++)
		{
			if ((f_PanelCutNestSheetPartList_0.Sheets[j].MaterialData.Quantity > 0) & f_PanelCutNestSheetPartList_0.Sheets[j].Enable)
			{
				num2 += f_PanelCutNestSheetPartList_0.Sheets[j].MaterialData.Width / 1000.0 * (f_PanelCutNestSheetPartList_0.Sheets[j].MaterialData.Height / 1000.0) * Convert.ToDouble(f_PanelCutNestSheetPartList_0.Sheets[j].MaterialData.Quantity);
			}
			if (j <= f_PanelCutNestSheetPartList_0.dataGridView_0.Rows.Count - 1)
			{
				f_PanelCutNestSheetPartList_0.dataGridView_0.Rows[j].Cells[8].Value = f_PanelCutNestSheetPartList_0.Sheets[j].Remain;
			}
		}
		f_PanelCutNestSheetPartList_0.textBox_3.Text = num.ToString("f2");
		f_PanelCutNestSheetPartList_0.textBox_2.Text = num3.ToString("f2");
		f_PanelCutNestSheetPartList_0.textBox_1.Text = num2.ToString("f2");
		f_PanelCutNestSheetPartList_0.textBox_0.Text = num2.ToString("f2");
	}

