	static void smethod_591(int int_0, [Optional][DefaultParameterValue(false)] bool bool_0, F_SelectedPlanes f_SelectedPlanes_0)
	{
		if (!((int_0 >= 0) & (int_0 <= f_SelectedPlanes_0.Planes.Count - 1)))
		{
			return;
		}
		f_SelectedPlanes_0.design_0.Entities.ClearSelection();
		for (int i = 0; i <= f_SelectedPlanes_0.design_0.Entities.Count - 1; i++)
		{
			if (f_SelectedPlanes_0.design_0.Entities[i].EntityData != null && f_SelectedPlanes_0.design_0.Entities[i].EntityData is CustomData)
			{
				CustomData customData = f_SelectedPlanes_0.design_0.Entities[i].EntityData as CustomData;
				if ((customData.typeDefination == entityTypeDefination.Plane) & (customData.RefIndex == int_0))
				{
					f_SelectedPlanes_0.design_0.Entities[i].Selected = true;
				}
			}
		}
		f_SelectedPlanes_0.design_0.Entities.DeleteSelected();
		if (!bool_0)
		{
			f_SelectedPlanes_0.Planes.RemoveAt(f_SelectedPlanes_0.SelectedPlane);
			f_SelectedPlanes_0.listBox_0.Items.RemoveAt(f_SelectedPlanes_0.SelectedPlane);
			f_SelectedPlanes_0.SelectedPlane--;
		}
		f_SelectedPlanes_0.design_0.Invalidate();
	}

