	static bool smethod_607(IntPoint intPoint_0, buClipperBase buClipperBase_0, IntPoint intPoint_1, IntPoint intPoint_2)
	{
		if (!(intPoint_1 == intPoint_0) && !(intPoint_1 == intPoint_2) && !(intPoint_0 == intPoint_2))
		{
			if (intPoint_1.X == intPoint_0.X)
			{
				return intPoint_2.Y > intPoint_1.Y == intPoint_2.Y < intPoint_0.Y;
			}
			return intPoint_2.X > intPoint_1.X == intPoint_2.X < intPoint_0.X;
		}
		return false;
	}

