	static void smethod_640(F_MarbleCamSettings f_MarbleCamSettings_0)
	{
		if (!((f_MarbleCamSettings_0.indexMat >= 0) & (f_MarbleCamSettings_0.indexMat <= buMarbleCalc.MaterialList.Count - 1)))
		{
			return;
		}
		f_MarbleCamSettings_0.spn_matsawcircularcutstep.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.SawForwardCircularStepDownDistance;
		f_MarbleCamSettings_0.spn_matsawcircularcutfirststep.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.SawForwardCircularStepFirstDownDistance;
		f_MarbleCamSettings_0.spn_matsawstraightcutstep.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.SawForwardStepDownDistance;
		f_MarbleCamSettings_0.spn_matsawstraightcutfirststep.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.SawForwardStepFirstDownDistance;
		f_MarbleCamSettings_0.spn_matsawcircularcutFwdspeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.SawForwardCircularCuttingVelocity;
		f_MarbleCamSettings_0.spn_matsawcircularcutBwdspeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.SawForwardCircularCuttingVelocity;
		f_MarbleCamSettings_0.spn_matsawcircularcutfirstspeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.SawForwardCircularFirstCuttingVelocity;
		f_MarbleCamSettings_0.spn_matsawstraightcutfirstspeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.SawForwardFirstCuttingVelocity;
		f_MarbleCamSettings_0.spn_matsawstraightcuttingsFwdspeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.SawForwardCuttingVelocity;
		f_MarbleCamSettings_0.spn_matsawstraightcuttingsBwdspeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.SawForwardCuttingVelocity;
		f_MarbleCamSettings_0.spn_matsawplungespeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.SawPlungeVelocity;
		f_MarbleCamSettings_0.spn_matsawplungefirstspeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.SawPlungeFirstVelocity;
		f_MarbleCamSettings_0.spn_matmillingcutstep.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MillingStepDown;
		f_MarbleCamSettings_0.spn_matmillingfirstcutstep.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MillingFirstStepDown;
		f_MarbleCamSettings_0.spn_matmillingcutspeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MillingCuttingVelocity;
		f_MarbleCamSettings_0.spn_matmillingfirstcutspeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MillingFirstCuttingVelocity;
		f_MarbleCamSettings_0.spn_matmillingplungespeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MillingPlungeVelocity;
		f_MarbleCamSettings_0.spn_matmillingplungefirstspeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MillingPlungeFirstVelocity;
		f_MarbleCamSettings_0.spn_matmillingdrillspeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MillingDrillVelocity;
		f_MarbleCamSettings_0.spn_matmillingheadcutstep.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MillingHeadStepDown;
		f_MarbleCamSettings_0.spn_matmillingheadfirstcutstep.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MillingHeadFirstStepDown;
		f_MarbleCamSettings_0.spn_matmillingheadcutspeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MillingHeadCuttingVelocity;
		f_MarbleCamSettings_0.spn_matmillingheadfirstcutspeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MillingHeadFirstCuttingVelocity;
		f_MarbleCamSettings_0.spn_matmillingheaddrillspeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MillingHeadDrillVelocity;
		f_MarbleCamSettings_0.spn_matmillingheadplungespeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MillingHeadPlungeVelocity;
		f_MarbleCamSettings_0.spn_matmillingheadplungefirstspeed.Value = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MillingHeadPlungeFirstVelocity;
		f_MarbleCamSettings_0.pictureBox_1.Image = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Photo;
		f_MarbleCamSettings_0.buTextBox_1.Text = buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].MaterialNames;
		if (buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MaterialHardness != MarbleMaterialHardness.VerySoft)
		{
			if (buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MaterialHardness != MarbleMaterialHardness.Soft)
			{
				if (buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MaterialHardness != MarbleMaterialHardness.Medium)
				{
					if (buMarbleCalc.MaterialList[f_MarbleCamSettings_0.indexMat].Parameters.MaterialHardness != MarbleMaterialHardness.Hard)
					{
						f_MarbleCamSettings_0.radioButton_8.Checked = true;
					}
					else
					{
						f_MarbleCamSettings_0.radioButton_10.Checked = true;
					}
				}
				else
				{
					f_MarbleCamSettings_0.radioButton_11.Checked = true;
				}
			}
			else
			{
				f_MarbleCamSettings_0.radioButton_9.Checked = true;
			}
		}
		else
		{
			f_MarbleCamSettings_0.radioButton_12.Checked = true;
		}
	}

