		f_MarbleMaterialList_0.spn_matsawplungespeed.Value = f_MarbleMaterialList_0.Settings.SawPlungeVelocity;
		f_MarbleMaterialList_0.spn_matmillingcutspeed.Value = f_MarbleMaterialList_0.Settings.MillingCuttingVelocity;
		f_MarbleMaterialList_0.spn_matmillingcutstep.Value = f_MarbleMaterialList_0.Settings.MillingStepDown;
		f_MarbleMaterialList_0.spn_matmillingfirstcutspeed.Value = f_MarbleMaterialList_0.Settings.MillingFirstCuttingVelocity;
		f_MarbleMaterialList_0.spn_matmillingfirstcutstep.Value = f_MarbleMaterialList_0.Settings.MillingFirstStepDown;
		f_MarbleMaterialList_0.spn_matmillingplungespeed.Value = f_MarbleMaterialList_0.Settings.MillingPlungeVelocity;
		f_MarbleMaterialList_0.spn_matmillingdrillspeed.Value = f_MarbleMaterialList_0.Settings.MillingDrillVelocity;
		f_MarbleMaterialList_0.spn_matmillingheadcutspeed.Value = f_MarbleMaterialList_0.Settings.MillingHeadCuttingVelocity;
