		if (f_MarbleMaterialList_0.Settings.MaterialHardness != MarbleMaterialHardness.VerySoft)
		{
			if (f_MarbleMaterialList_0.Settings.MaterialHardness != MarbleMaterialHardness.Soft)
			{
				if (f_MarbleMaterialList_0.Settings.MaterialHardness != MarbleMaterialHardness.Medium)
				{
					if (f_MarbleMaterialList_0.Settings.MaterialHardness != MarbleMaterialHardness.Hard)
					{
