	static void smethod_673(F_MachineOtherCodeCfg f_MachineOtherCodeCfg_0)
	{
		string text = f_MachineOtherCodeCfg_0.string_0 + " Apply";
		try
		{
			f_MachineOtherCodeCfg_0.OtherCode.TimeAsSec = (double)f_MachineOtherCodeCfg_0.spn_time.Value;
			f_MachineOtherCodeCfg_0.OtherCode.OtherCodeExplanation = f_MachineOtherCodeCfg_0.textBox_1.Text;
			f_MachineOtherCodeCfg_0.OtherCode.OtherCode = f_MachineOtherCodeCfg_0.textBox_0.Text;
			f_MachineOtherCodeCfg_0.OtherCode.ExtraCode = f_MachineOtherCodeCfg_0.textBox_2.Text;
		}
		catch (Exception ex)
		{
			buLogVer5.addToLog(f_MachineOtherCodeCfg_0.string_0, text, "Exception", ex.Message);
			buException.throwException(ex, text, ShowMessageBox: true);
		}
	}

	static void smethod_674(F_SketchLibrary f_SketchLibrary_0)
	{
		f_SketchLibrary_0.list_0.Clear();
		buFile.GetFilesInDirectory(f_SketchLibrary_0.varLib.pathLibrary, ".bulib5", ref f_SketchLibrary_0.list_0);
		if (f_SketchLibrary_0.buListBox_0.Items.Count > 0)
		{
			f_SketchLibrary_0.buListBox_0.Items.Clear();
		}
		for (int i = 0; i <= f_SketchLibrary_0.list_0.Count - 1; i++)
		{
			FileItem item = new FileItem(f_SketchLibrary_0.list_0[i]);
			f_SketchLibrary_0.buListBox_0.Items.Add(item);
		}
	}

