	static void smethod_808(F_PanelCutNestSheetPartList f_PanelCutNestSheetPartList_0)
	{
		f_PanelCutNestSheetPartList_0.timer_0.Enabled = false;
		f_PanelCutNestSheetPartList_0.dataGridView_0.Rows.Clear();
		for (int i = 0; i <= f_PanelCutNestSheetPartList_0.Sheets.Count - 1; i++)
		{
			buNestingSheet buNestingSheet2 = new buNestingSheet(f_PanelCutNestSheetPartList_0.Sheets[i]);
			Image Img = new Bitmap(100, 100);
			f_PanelCutNestSheetPartList_0.SheetPointsToImage(f_PanelCutNestSheetPartList_0.Sheets[i], f_PanelCutNestSheetPartList_0.Settings.Draw.GridPartSheetPreviewWidth, f_PanelCutNestSheetPartList_0.Settings.Draw.GridPartSheetHeight, ref Img);
			DataGridViewRowCollection rows = f_PanelCutNestSheetPartList_0.dataGridView_0.Rows;
			bool enable = buNestingSheet2.Enable;
			string name = buNestingSheet2.MaterialData.Name;
			double width = buNestingSheet2.MaterialData.Width;
			double height = buNestingSheet2.MaterialData.Height;
			int quantity = buNestingSheet2.MaterialData.Quantity;
			int used = buNestingSheet2.Used;
			int remain = buNestingSheet2.Remain;
			string fileName = buNestingSheet2.FileName;
			double thickness = buNestingSheet2.MaterialData.Thickness;
			string itemNo = buNestingSheet2.MaterialData.ItemNo;
			string other = buNestingSheet2.MaterialData.Other;
			string aux = buNestingSheet2.MaterialData.Aux;
			rows.Add(smethod_561(width, quantity, itemNo, aux, name, remain, i + 1, height, Img, thickness, other, f_PanelCutNestSheetPartList_0, fileName, used, enable));
			f_PanelCutNestSheetPartList_0.dataGridView_0.Rows[i].DefaultCellStyle.ForeColor = Color.Black;
			f_PanelCutNestSheetPartList_0.dataGridView_0.Rows[i].Height = f_PanelCutNestSheetPartList_0.Settings.Draw.GridPartSheetHeight;
			if ((buNestingSheet2.Remain <= 0) & (buNestingSheet2.MaterialData.Quantity >= 0))
			{
				f_PanelCutNestSheetPartList_0.dataGridView_0.Rows[i].DefaultCellStyle.ForeColor = Color.Red;
			}
		}
		f_PanelCutNestSheetPartList_0.dataGridView_1.Rows.Clear();
